    class Singleton {
    private static Singleton obj = new Singleton();
    private Singleton() {}

    public static Singleton getInstance() { return obj; }
}


            Python

    class Singleton:
    _instance = None

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super(Singleton, cls).__new__(cls)
        return cls._instance

    @staticmethod
    def get_instance():
        return Singleton()


            JavaScript

    class Singleton {
    static obj = new Singleton();

    private constructor() {}

    static getInstance() {
        return Singleton.obj;
    }
}

The singleton instance is created in a static initializer, which runs when the class is loaded.This approach is thread-safe because JVM handles static initialization.Best used when the singleton class is lightweight and needed throughout the program execution.4. Double-Checked Locking (Most Efficient)Use “Double Checked Locking” to implement singleton design patternExample: Double Checked Locking based Java implementation of singleton design pattern
            C++

    #include <mutex>

class Singleton {
private:
    static Singleton* obj;
    static std::mutex mtx;

    Singleton() {}

public:
    static Singleton* getInstance() {
        if (obj == nullptr) {
            std::lock_guard<std::mutex> lock(mtx);

            if (obj == nullptr)
                obj = new Singleton();
        }

        return obj;
    }
};

Singleton* Singleton::obj = nullptr;
std::mutex Singleton::mtx;


            Java

    import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class Singleton {
    private static Singleton obj;
    private static final Lock lock = new ReentrantLock();

    private Singleton() {}

    public static Singleton getInstance() {
        if (obj == null) {
            lock.lock();
            try {
                if (obj == null)
                    obj = new Singleton();
            } finally {
                lock.unlock();
            }
        }
        return obj;
    }
}


            Python

    import threading

class Singleton:
    obj = None
    mtx = threading.Lock()

    def __new__(cls):
        if cls.obj is None:
            with cls.mtx:
                if cls.obj is None:
                    cls.obj = super(Singleton, cls).__new__(cls)
        return cls.obj

    @staticmethod
    def get_instance():
        return Singleton()


            JavaScript

    class Singleton {
    static obj = null;
    static mtx = new Map();

    constructor() {}

    static getInstance() {
        if (Singleton.obj == null) {
            const lock = Singleton.mtx.get('lock') || new Object();
            Singleton.mtx.set('lock', lock);

            if (Singleton.obj == null) {
                Singleton.obj = new Singleton();
            }
            Singleton.mtx.delete('lock');
        }

        return Singleton.obj;
    }
}

The obj is declared volatile to ensure correct handling by multiple threads during initialization.This approach reduces the overhead of synchronizing every time getInstance() is called.It provides a thread-safe and efficient way to create the singleton instance.5. Static Inner Class (Best Java-Specific Way) In Java, a Singleton can be implemented using a static inner class.A class is loaded into memory only once by the JVM.An inner class is loaded only when it is referenced.Therefore, the Singleton instance is created lazily, only when the getInstance() method accesses the inner class.Example: using class loading concept singleton design pattern
            C++

    #include <iostream>
class Singleton {
private:
    Singleton() {
        std::cout << "Instance created" << std::endl;
    }
    static Singleton* instance;
public:
    static Singleton* getInstance() {
        static Singleton instance;
        return &instance;
    }
};
